const SIZES = 12
function makeSizes (src: Image): Image[] {
    let list: Image[] = []
    for (let i = 0; i < SIZES; i++) {
        let f = (i + 1) / SIZES
        let w = Math.max(1, Math.round(src.width * f))
        let h = Math.max(1, Math.round(src.height * f))
        let out = image.create(w, h)
        for (let y = 0; y < h; y++) {
            for (let x = 0; x < w; x++) {
                out.setPixel(x, y, src.getPixel(Math.floor(x * src.width / w), Math.floor(y * src.height / h)))
            }
        }
        list.push(out)
    }
    return list
}
function flipped (src: Image): Image {
    let c = src.clone()
    c.flipX()
    return c
}
function recolor (src: Image, a: number, b: number, c: number, d: number): Image {
    let out = src.clone()
    out.replace(a, b)
    out.replace(c, d)
    return out
}
