//  السيارة | The car
// =====================================================
let carX = 0
let carY = 0
let carZ = 0
let velX = 0
let velY = 0
let heading = 0
let speed = 0
let sideSpeed = 0
let vz = 0
let airborne = false
let pitch = 0
let roll = 0
let airPitch = 0
let lateralLean = 0
let tumbleUntil = 0
let wasTumbling = false
let lastGround = 0
let lastGroundVz = 0
let steerNow = 0
let sliding = false
// نوابض المساعدات وانتقال الوزن | suspension spring and weight transfer
let bodyY = 0
let bodyVY = 0
let bodyPitch = 0

// ---------- الكاميرا | Camera ----------
let camX = 0
let camY = 0
let camZ = 0
let camHeading = 0
let CAM_BACK = 70
let CAM_UP = 52
let HORIZON_BASE = 30
let HORIZON = 30
let SCALE = 110
let FOV = 0.75
let camBackNow = 70
let shake = 0

// ---------- السباق | Race ----------
let flagX: number[] = []
let flagY: number[] = []
let nextFlag = 0
let raceStarted = false
let raceOver = false
let startTime = 0
let penalty = 0
let rollovers = 0
let finalTime = 0
let lastBeep = 0
let nextEngineSound = 0
let message = ""
let messageUntil = 0
let campX = 0
let campY = 0
let SHADOW_LEVEL = 0.25
let rolloverHandlers: (() => void)[] = []
let flagHandlers: (() => void)[] = []

// ---------- السيارات الثانية | Other cars ----------
let aiX: number[] = []
let aiY: number[] = []
let aiHead: number[] = []
let aiSpeed: number[] = []
let aiTX: number[] = []
let aiTY: number[] = []
// ---------- الجمال | Camels ----------
let camelX: number[] = []
let camelY: number[] = []
let camelHead: number[] = []
let camelSpeed: number[] = []
let herdX = 0
let herdY = 0

// ---------- الغبار | Dust ----------
let partX: number[] = []
let partY: number[] = []
let partVX: number[] = []
