let partColor: number[] = []

function say (text: string, ms: number) {
    message = text
    messageUntil = game.runtime() + ms
}

function updateCar (dt: number) {
    let tumbling = game.runtime() < tumbleUntil
    if (wasTumbling && !(tumbling)) {
        // بعد الانقلاب: نعدّل السيارة باتجاه النزلة | after rolling: set the car facing downhill
        let gx = groundAt(carX + 6, carY) - groundAt(carX - 6, carY)
        let gy = groundAt(carX, carY + 6) - groundAt(carX, carY - 6)
        if (Math.abs(gx) + Math.abs(gy) > 0.5) {
            heading = Math.atan2(0 - gy, 0 - gx)
        }
        roll = 0
        lateralLean = 0
        velX = 0
        velY = 0
    }
    wasTumbling = tumbling
    let fx = Math.cos(heading)
    let fy = Math.sin(heading)
    let rx = 0 - fy
    let ry = fx
    speed = velX * fx + velY * fy
    sideSpeed = velX * rx + velY * ry
    // اللف | steering
    steerNow = 0
    if (!(tumbling) && !(airborne) && raceStarted && !(raceOver)) {
        if (controller.left.isPressed()) {
            steerNow = -1
        } else if (controller.right.isPressed()) {
            steerNow = 1
        }
    }
    let turn = steerNow * TURN_RATE * Math.min(1, Math.abs(speed) / 110)
    if (speed < 0) {
        turn = 0 - turn
    }
    // نلف السيارة أول، وبعدين نشوف وين رايحة السرعة | turn the car first, then see where the speed goes
    if (!(tumbling) && !(airborne)) {
        heading += turn * dt
    }
    fx = Math.cos(heading)
    fy = Math.sin(heading)
    rx = 0 - fy
    ry = fx
    speed = velX * fx + velY * fy
    sideSpeed = velX * rx + velY * ry
    // الأربع كفرات على الرمل | the four wheels on the sand
    let flX = carX + fx * 20 - rx * 11
    let flY = carY + fy * 20 - ry * 11
    let frX = carX + fx * 20 + rx * 11
    let frY = carY + fy * 20 + ry * 11
    let blX = carX - fx * 20 - rx * 11
    let blY = carY - fy * 20 - ry * 11
    let brX = carX - fx * 20 + rx * 11
    let brY = carY - fy * 20 + ry * 11
    let hFL = groundAt(flX, flY)
    let hFR = groundAt(frX, frY)
    let hBL = groundAt(blX, blY)
    let hBR = groundAt(brX, brY)
    let groundPitch = toDeg(Math.atan2((hFL + hFR) / 2 - (hBL + hBR) / 2, 40))
    let groundRoll = toDeg(Math.atan2((hFL + hBL) / 2 - (hFR + hBR) / 2, 22))
    let engine = 0
    let braking = false
    if (tumbling) {
        speed = speed * 0.9
        sideSpeed = sideSpeed * 0.9
    } else if (!(airborne)) {
        if (raceStarted && !(raceOver)) {
            if (controller.A.isPressed()) {
                engine = ENGINE
            } else if (controller.B.isPressed()) {
                braking = speed > 5
                if (braking) {
                    engine = 0 - ENGINE * 1.8
                } else {
                    engine = 0 - ENGINE * 0.6
                }
            }
        }
        // الجاذبية على الطلعة والنزلة | gravity on climbs and descents
        let slopeForce = 0 - GRAVITY * Math.sin(groundPitch * Math.PI / 180)
        let drag = 0 - speed * SAND_DRAG * 0.25 - Math.sign(speed) * 18
        // الرمل يمسك السيارة إذا وقفت | sand holds a stopped car
        if (engine == 0 && Math.abs(speed) < 15 && Math.abs(groundPitch) < 28) {
            speed = 0
            slopeForce = 0
            drag = 0
        }
        speed += (engine + slopeForce + drag) * dt
        speed = Math.max(-90, Math.min(MAX_SPEED, speed))
        // الكفرات تمسك الرمل لحد 0.7g، الزيادة تزحلق السيارة على جنب
        // tyres grip the sand up to 0.7g; anything more makes the car slide sideways
        let sideGravity = GRAVITY * Math.sin(groundRoll * Math.PI / 180)
        sideSpeed += sideGravity * dt
        let grip = SAND_GRIP * GRAVITY * dt
        if (Math.abs(sideSpeed) <= grip) {
            sideSpeed = 0
        } else {
            sideSpeed += 0 - Math.sign(sideSpeed) * grip
        }
        sliding = Math.abs(sideSpeed) > 25
    }
    if (!(airborne)) {
        velX = fx * speed + rx * sideSpeed
        velY = fy * speed + ry * sideSpeed
    }
    carX += velX * dt
    carY += velY * dt
    // الطيران من فوق القمة | flying off a crest
    let newGround = groundAt(carX, carY)
    let groundVz = (newGround - lastGround) / Math.max(0.001, dt)
    if (!(airborne)) {
        if (vz > groundVz + 70 && speed > 120) {
            airborne = true
            airPitch = pitch
            takeoffSpeed = Math.abs(speed)
            music.play(music.melodyPlayable(music.jumpUp), music.PlaybackMode.InBackground)
        } else {
            // النوابض تمتص المطبات | the suspension soaks up bumps
            bodyVY += 0 - (groundVz - lastGroundVz) * 0.12
            vz = groundVz
            carZ = newGround
        }
    }
    if (airborne) {
        vz += 0 - GRAVITY * 2.2 * dt
        carZ += vz * dt
        // في الهوا السيارة تلف شوي باتجاه الرمل، وكل ما زادت السرعة يقل الوقت
        // in the air the car turns toward the sand below; the faster you go, the less time it has
        let below = groundAt(carX + fx * 20, carY + fy * 20) - groundAt(carX - fx * 20, carY - fy * 20)
        let targetPitch = toDeg(Math.atan2(below, 40))
        let rate = Math.max(10, 42 - Math.abs(speed) * 0.09) * dt
        airPitch += Math.max(0 - rate, Math.min(rate, targetPitch - airPitch))
        if (carZ <= newGround) {
            carZ = newGround
            airborne = false
            bodyVY += vz * 0.25
            // تنقلب بس إذا طرت بسرعة كبيرة جداً ونزلت غلط | only crash when you flew very fast and landed badly
            if (takeoffSpeed > CRASH_SPEED) {
                rollOver("TOO FAST! SLOW DOWN")
            } else {
                velX = velX * 0.88
                velY = velY * 0.88
                shake = 3
                music.play(music.melodyPlayable(music.thump), music.PlaybackMode.InBackground)
                dustBurst(8)
            }
            vz = 0
        }
    }
    lastGround = newGround
    lastGroundVz = groundVz
    // النوابض | suspension spring
    bodyVY += (0 - 160 * bodyY - 11 * bodyVY) * dt
    bodyY += bodyVY * dt
    bodyY = Math.max(-5, Math.min(5, bodyY))
    // انتقال الوزن: البنزين يرفع الخشم والفرامل تنزّله | weight transfer: gas lifts the nose, brakes drop it
    let wantBodyPitch = 0
    if (engine > 0) {
        wantBodyPitch = 4
    } else if (braking) {
        wantBodyPitch = -5
    }
    bodyPitch += (wantBodyPitch - bodyPitch) * Math.min(1, dt * 6)
    // ميلان الجسم من قوة اللف | body lean from the turning force
    let used = Math.min(SAND_GRIP * GRAVITY, Math.abs(speed * turn))
    let lean = toDeg(Math.atan2(used, GRAVITY)) * 0.6 * Math.sign(turn * speed)
    lateralLean += (lean - lateralLean) * Math.min(1, dt * 6)
    if (airborne) {
        pitch = airPitch
    } else {
        pitch += (groundPitch - pitch) * Math.min(1, dt * 12)
        roll += (groundRoll - roll) * Math.min(1, dt * 12)
        // آثار الكفرات | tyre tracks
        if (Math.abs(speed) > 10) {
            markTrack(blX, blY)
            markTrack(brX, brY)
        }
    }
    // اهتزاز في النزلات السريعة | shaking on fast descents
    if (!(airborne) && pitch < -12 && speed > 150) {
        shake = Math.max(shake, 1)
    }
    speed = velX * Math.cos(heading) + velY * Math.sin(heading)
}

function totalTilt (): number {
    return roll + lateralLean
}

function rollOver (text: string) {
    tumbleUntil = game.runtime() + 2000
    rollovers += 1
    penalty += 5
    velX = velX * 0.3
    velY = velY * 0.3
    shake = 5
    dustBurst(16)
    music.play(music.melodyPlayable(music.bigCrash), music.PlaybackMode.InBackground)
    say(text, 2000)
    for (let h of rolloverHandlers) {
        h()
    }
}

// صوت الماكينة يعلى مع السرعة | the engine sound rises with speed
function engineSound () {
    if (game.runtime() < nextEngineSound || !(raceStarted)) {
        return
    }
    nextEngineSound = game.runtime() + 110
    let f = 55 + Math.abs(speed) * 0.42
    let vol = 28
    if (controller.A.isPressed() && !(airborne)) {
        f += 25
        vol = 45
    }
    music.play(music.createSoundEffect(WaveShape.Sawtooth, f, f + 8, vol, vol, 130, SoundExpressionEffect.None, InterpolationCurve.Linear), music.PlaybackMode.InBackground)
}

function updateCamera (dt: number) {
    let d = camHeading - heading
    while (d > Math.PI) {
        d += 0 - 2 * Math.PI
    }
    while (d < 0 - Math.PI) {
        d += 2 * Math.PI
    }
    camHeading += 0 - d * Math.min(1, dt * 5)
    // لو وراك طعس، الكاميرا تقرب | if a dune is behind you, the camera moves closer
    camBackNow = CAM_BACK
    for (let back = CAM_BACK; back >= 30; back += -10) {
        camBackNow = back
        if (groundAt(carX - Math.cos(camHeading) * back, carY - Math.sin(camHeading) * back) + 12 <= carZ + CAM_UP) {
            break
        }
    }
    camX = carX - Math.cos(camHeading) * camBackNow
    camY = carY - Math.sin(camHeading) * camBackNow
    camZ += (carZ + CAM_UP - camZ) * Math.min(1, dt * 6)
    camZ = Math.max(camZ, groundAt(camX, camY) + 12)
    let carScreenY = (camZ - carZ) * SCALE / camBackNow + HORIZON_BASE
    let wantHorizon = HORIZON_BASE
    if (carScreenY > 104) {
        wantHorizon = HORIZON_BASE - (carScreenY - 104)
    }
    HORIZON += (wantHorizon - HORIZON) * Math.min(1, dt * 8)
    // اهتزاز الكاميرا | camera shake
    if (shake > 0) {
        HORIZON += Math.randomRange(0 - shake, shake) * 0.6
        camHeading += Math.randomRange(-10, 10) * 0.0004 * shake
        shake = Math.max(0, shake - dt * 8)
    }
}

// =====================================================
//  السيارات الثانية والجمال | Other cars and camels
// =====================================================
function spawnWorld () {
    for (let i = 0; i < AI_COUNT; i++) {
        let a = (i + 0.5) / Math.max(1, AI_COUNT) * 2 * Math.PI
        aiX.push(carX + Math.cos(a) * 600)
        aiY.push(carY + Math.sin(a) * 600)
        aiHead.push(a + 1.5)
        aiSpeed.push(0)
        aiTX.push(carX)
        aiTY.push(carY)
        pickAiTarget(i)
    }
    // القطيع في الطريق للعلم الأول | the herd is on the way to the first flag
    herdX = carX + wrapDelta(flagX[0] - carX) * 0.55 + 90
    herdY = carY + wrapDelta(flagY[0] - carY) * 0.55 - 90
    for (let i = 0; i < CAMEL_COUNT; i++) {
        camelX.push(herdX + Math.randomRange(-50, 50))
        camelY.push(herdY + Math.randomRange(-50, 50))
        camelHead.push(Math.randomRange(0, 628) / 100)
        camelSpeed.push(Math.randomRange(10, 20))
    }
}
function pickAiTarget (i: number) {
    let a = Math.randomRange(0, 628) / 100
    let r = Math.randomRange(300, 700)
    aiTX[i] = aiX[i] + Math.cos(a) * r
    aiTY[i] = aiY[i] + Math.sin(a) * r
}
function updateWorld (dt: number) {
    for (let i = 0; i < aiX.length; i++) {
        let dx = wrapDelta(aiTX[i] - aiX[i])
        let dy = wrapDelta(aiTY[i] - aiY[i])
        if (dx * dx + dy * dy < 70 * 70) {
            pickAiTarget(i)
        }
        let want = Math.atan2(dy, dx)
        let d = want - aiHead[i]
        while (d > Math.PI) {
            d += 0 - 2 * Math.PI
        }
        while (d < 0 - Math.PI) {
            d += 2 * Math.PI
        }
        aiHead[i] += Math.max(-1.2 * dt, Math.min(1.2 * dt, d))
        let fx = Math.cos(aiHead[i])
        let fy = Math.sin(aiHead[i])
        let slope = (groundAt(aiX[i] + fx * 20, aiY[i] + fy * 20) - groundAt(aiX[i] - fx * 20, aiY[i] - fy * 20)) / 40
        aiSpeed[i] += (ENGINE * 0.75 - GRAVITY * slope - aiSpeed[i] * SAND_DRAG * 0.25) * dt
        aiSpeed[i] = Math.max(30, Math.min(260, aiSpeed[i]))
        aiX[i] += fx * aiSpeed[i] * dt
        aiY[i] += fy * aiSpeed[i] * dt
        markTrack(aiX[i] - fx * 20 - fy * 11, aiY[i] - fy * 20 + fx * 11)
        markTrack(aiX[i] - fx * 20 + fy * 11, aiY[i] - fy * 20 - fx * 11)
        // تصادم مع سيارتك | bumping into your car
        let px = wrapDelta(carX - aiX[i])
        let py = wrapDelta(carY - aiY[i])
        if (px * px + py * py < 34 * 34 && !(airborne)) {
            let dist = Math.max(1, Math.sqrt(px * px + py * py))
            velX = velX * 0.5 + px / dist * 60
            velY = velY * 0.5 + py / dist * 60
            aiSpeed[i] = aiSpeed[i] * 0.4
            shake = 3
            if (game.runtime() > messageUntil) {
                say("BUMP!", 700)
                music.play(music.melodyPlayable(music.knock), music.PlaybackMode.InBackground)
            }
        }
    }
    for (let i = 0; i < camelX.length; i++) {
        let px = wrapDelta(carX - camelX[i])
        let py = wrapDelta(carY - camelY[i])
        let near = px * px + py * py
        if (near < 130 * 130) {
            // الجمل يبعد عن السيارة | the camel walks away from the car
            camelHead[i] = Math.atan2(0 - py, 0 - px)
            camelSpeed[i] = 55
        } else {
            let hx = wrapDelta(herdX - camelX[i])
            let hy = wrapDelta(herdY - camelY[i])
            if (hx * hx + hy * hy > 90 * 90) {
                camelHead[i] = Math.atan2(hy, hx)
            } else if (Math.percentChance(1)) {
                camelHead[i] += Math.randomRange(-100, 100) / 100
            }
            camelSpeed[i] = Math.max(12, camelSpeed[i] - 20 * dt)
        }
        camelX[i] += Math.cos(camelHead[i]) * camelSpeed[i] * dt
        camelY[i] += Math.sin(camelHead[i]) * camelSpeed[i] * dt
        if (near < 24 * 24 && Math.abs(speed) > 40 && game.runtime() > tumbleUntil) {
            velX = velX * 0.15
            velY = velY * 0.15
            shake = 4
            say("CAMEL! SLOW DOWN", 1200)
            music.play(music.melodyPlayable(music.thump), music.PlaybackMode.InBackground)
        }
    }
    // القطيع يمشي على راحته | the herd drifts slowly
    herdX += Math.cos(game.runtime() / 9000) * 6 * dt
    herdY += Math.sin(game.runtime() / 7000) * 6 * dt
}

