function collectThings () {
    thingX = []
    thingY = []
    thingKind = []
    thingRef = []
    thingDepth = []
    thingCol = []
    thingOcc = []
    if (nextFlag < flagX.length) {
        addThing(flagX[nextFlag], flagY[nextFlag], T_FLAG, 0)
    }
    addThing(campX, campY, T_TENT, 0)
    addThing(campX - 30, campY + 34, T_FIRE, 0)
    for (let i = 0; i < camelX.length; i++) {
        addThing(camelX[i], camelY[i], T_CAMEL, i)
    }
    for (let i = 0; i < aiX.length; i++) {
        addThing(aiX[i], aiY[i], T_CAR, i)
    }
    let fx = Math.cos(camHeading)
    let fy = Math.sin(camHeading)
    for (let t = 0; t < thingX.length; t++) {
        let rx = wrapDelta(thingX[t] - camX)
        let ry = wrapDelta(thingY[t] - camY)
        thingDepth[t] = rx * fx + ry * fy
        thingCol[t] = Math.round(80 + (rx * (0 - fy) + ry * fx) / (FOV * Math.max(1, thingDepth[t])) * 80)
    }
}

let BAYER = [0.125, 0.625, 0.875, 0.375]
let SHADES = [6, 5, 4, 3]
// طريقة رسم الرمل | how the sand is drawn
let RENDER_STYLE = 2
let FOG_START = 850
let FOG_AMOUNT = 0.6
let CONTRAST = 1.5
let BRIGHTEN = 0.02
// تدرج الرمل من الظل للضوء (6 ألوان) | the sand ramp from shadow to light (6 tones)
let RAMP = [6, 5, 4, 12, 3, 9]
// نمط التنقيط 4×4 | 4x4 dither pattern
let BAYER4 = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5]
let prevV: number[] = []
for (let i = 0; i < 160; i++) {
    prevV.push(0.5)
}
// تنوع ألوان الرمل في المنطقة | sand colour variation across the area
let tint: Buffer = null
function lightAt (wx: number, wy: number): number {
    let fx = wx / CELL
    let fy = wy / CELL
    let x0 = Math.floor(fx)
    let y0 = Math.floor(fy)
    let tx = fx - x0
    let ty = fy - y0
    let a = sunLight[((y0 % MAP + MAP) % MAP) * MAP + (x0 % MAP + MAP) % MAP]
    let b = sunLight[((y0 % MAP + MAP) % MAP) * MAP + ((x0 + 1) % MAP + MAP) % MAP]
    let c = sunLight[(((y0 + 1) % MAP + MAP) % MAP) * MAP + (x0 % MAP + MAP) % MAP]
    let d = sunLight[(((y0 + 1) % MAP + MAP) % MAP) * MAP + ((x0 + 1) % MAP + MAP) % MAP]
    return ((a * (1 - tx) + b * tx) * (1 - ty) + (c * (1 - tx) + d * tx) * ty) / 255
}
function drawTerrain (target: Image) {
    // السماء | the sky
    target.fillRect(0, 0, 160, 120, 7)
    target.fillRect(0, 0, 160, 12, 8)
    for (let y = 12; y < 22; y++) {
        for (let x = (y % 2) * 2; x < 160; x += 4) {
            target.setPixel(x, y, 8)
        }
    }
    let sunY = 14
    if (timeOfDay == DayTime.Sunset) {
        sunY = Math.floor(HORIZON) - 4
    }
    target.fillCircle(130, sunY, 9, 9)
    target.fillCircle(130, sunY, 6, 13)
    for (let i = 0; i < 160; i++) {
        ybuf[i] = 120
        edgeZ[i] = 0
        edgeC[i] = 4
    }
    collectThings()
    let fwdX = Math.cos(camHeading)
    let fwdY = Math.sin(camHeading)
    let rightX = 0 - fwdY
    let rightY = fwdX
    let z = 4
    let dz = 2
    let slice = 0
    while (z < 1400) {
        slice += 1
        let lx = camX + (fwdX - rightX * FOV) * z
        let ly = camY + (fwdY - rightY * FOV) * z
        let stepX = rightX * FOV * 2 * z / 160
        let stepY = rightY * FOV * 2 * z / 160
        let inv = SCALE / z
        let near = z < 260
        let far = z > 900
        for (let i = 0; i < 160; i++) {
            let cx = (Math.floor(lx / CELL) % MAP + MAP) % MAP
            let cy = (Math.floor(ly / CELL) % MAP + MAP) % MAP
            let idx = cy * MAP + cx
            let h = heights[idx]
            if (near) {
                h = groundAt(lx, ly)
            }
            let sy = Math.floor((camZ - h) * inv + HORIZON)
            if (sy < ybuf[i]) {
                let c = 9
                let v = sunLight[idx]
                if (v < 255) {
                    // ظلال ناعمة بالتنقيط | smooth shading with dithering
                    let level = v / 255 * 3
                    let base = Math.floor(level)
                    let frac = level - base
                    if (near) {
                        // قريب: ظلال واضحة | close: clean shade bands
                        if (frac > 0.5) {
                            base += 1
                        }
                    } else if (frac > 0.7 || (frac > 0.3 && (i + slice) % 2 == 0)) {
                        // بعيد: تنقيط خفيف | far: light dithering
                        base += 1
                    }
                    c = SHADES[Math.min(3, base)]
                }
                if (z < 450 && tracks[idx] == 1 && c != 6) {
                    // آثار الكفرات أغمق | tyre tracks are darker
                    if (c == 9) {
                        c = 4
                    } else {
                        c += 1
                    }
                }
                // البعيد يفتح لونه مع الغبار | far away gets lighter in the haze
                if (z > 1050) {
                    c = 9
                } else if (far && (c == 5 || c == 6)) {
                    c = c - 1
                } else if (far && c == 4) {
                    c = 3
                } else if (z > 650 && c == 6) {
                    c = 5
                }
                // خط على حافة الطعس اللي قدام | an outline on the edge of the dune in front
                if (ybuf[i] < 120 && z > edgeZ[i] * 1.35 + 20) {
                    let edge = 6
                    if (edgeC[i] == 3 || edgeC[i] == 9) {
                        edge = 1
                    } else if (edgeC[i] == 4) {
                        edge = 9
                    }
                    target.setPixel(i, ybuf[i], edge)
                }
                target.fillRect(i, sy, 1, ybuf[i] - sy, c)
                ybuf[i] = sy
                edgeZ[i] = z
                edgeC[i] = c
            }
            lx += stepX
            ly += stepY
        }
        // نسجّل الرمل اللي قدام كل شي | remember the sand in front of each thing
        for (let t = 0; t < thingX.length; t++) {
            if (thingDepth[t] > z - dz && thingDepth[t] <= z && thingCol[t] >= 0 && thingCol[t] < 160) {
                thingOcc[t] = ybuf[thingCol[t]]
            }
        }
        z += dz
        dz = dz * 1.045
    }
}

// رسم ناعم: كل بكسل لونه متدرج بين القريب والبعيد | smooth drawing: every pixel blends between near and far
function drawTerrainSmooth (target: Image, edges: boolean) {
    target.fillRect(0, 0, 160, 120, 7)
    target.fillRect(0, 0, 160, 10, 8)
    for (let y = 10; y < 26; y++) {
        for (let x = 0; x < 160; x++) {
            if (BAYER4[(y % 4) * 4 + x % 4] < (26 - y) * 1) {
                target.setPixel(x, y, 8)
            }
        }
    }
    let sunY = 14
    if (timeOfDay == DayTime.Sunset) {
        sunY = Math.floor(HORIZON) - 4
    }
    target.fillCircle(130, sunY, 9, 9)
    target.fillCircle(130, sunY, 6, 13)
    for (let i = 0; i < 160; i++) {
        ybuf[i] = 120
        edgeZ[i] = 0
        prevV[i] = -1
    }
    collectThings()
    let fwdX = Math.cos(camHeading)
    let fwdY = Math.sin(camHeading)
    let rightX = 0 - fwdY
    let rightY = fwdX
    let z = 4
    let dz = 2
    while (z < 1400) {
        let lx = camX + (fwdX - rightX * FOV) * z
        let ly = camY + (fwdY - rightY * FOV) * z
        let stepX = rightX * FOV * 2 * z / 160
        let stepY = rightY * FOV * 2 * z / 160
        let inv = SCALE / z
        let near = z < 200
        // الغبار يزيد مع البعد | haze grows with distance
        let fog = Math.max(0, Math.min(1, (z - FOG_START) / (1400 - FOG_START))) * FOG_AMOUNT
        for (let i = 0; i < 160; i++) {
            let cx = (Math.floor(lx / CELL) % MAP + MAP) % MAP
            let cy = (Math.floor(ly / CELL) % MAP + MAP) % MAP
            let idx = cy * MAP + cx
            let h = heights[idx]
            let v = sunLight[idx] / 255
            if (near) {
                h = groundAt(lx, ly)
                v = lightAt(lx, ly)
            }
            if (tracks[idx] == 1 && z < 450) {
                v = v * 0.8
            }
            // تنوع خفيف في لون الرمل | gentle sand colour variation
            v = v + (tint[idx] - 128) / 900
            // نزيد الفرق بين الضوء والظل | boost the difference between light and shadow
            v = (v - 0.5) * CONTRAST + 0.5 + BRIGHTEN
            let sy = Math.floor((camZ - h) * inv + HORIZON)
            if (sy < ybuf[i]) {
                let bottom = ybuf[i]
                let vBottom = prevV[i]
                if (vBottom < 0) {
                    vBottom = v
                }
                if (edges && bottom < 120 && z > edgeZ[i] * 1.35 + 20) {
                    // حافة طعس قدام طعس: نخلي القمة تلمع | a dune edge in front of another: the crest shines
                    vBottom = Math.min(1.05, vBottom + 0.35)
                }
                // حساب سريع بالأرقام الصحيحة | fast integer maths
                let span = Math.max(1, bottom - sy)
                let L = Math.floor(Math.max(0, Math.min(1.2, v)) * 1280)
                let L1 = Math.floor(Math.max(0, Math.min(1.2, vBottom)) * 1280)
                let dL = Math.floor((L1 - L) / span)
                let y0 = sy
                if (y0 < 0) {
                    L += dL * (0 - y0)
                    y0 = 0
                }
                let fogI = Math.floor(fog * 16)
                let col = i & 3
                for (let y = y0; y < bottom; y++) {
                    let th = BAYER4[((y & 3) << 2) | col]
                    let c = 9
                    if (th >= fogI) {
                        let lv = ((L >> 4) + th) >> 4
                        if (lv > 5) {
                            lv = 5
                        } else if (lv < 0) {
                            lv = 0
                        }
                        c = RAMP[lv]
                    }
                    target.setPixel(i, y, c)
                    L += dL
                }
                ybuf[i] = sy
                edgeZ[i] = z
            }
            prevV[i] = v
            lx += stepX
            ly += stepY
        }
        for (let t = 0; t < thingX.length; t++) {
            if (thingDepth[t] > z - dz && thingDepth[t] <= z && thingCol[t] >= 0 && thingCol[t] < 160) {
                thingOcc[t] = ybuf[thingCol[t]]
            }
        }
        z += dz
        dz = dz * 1.045
    }
}

let screenX = 0
let screenY = 0
function project (wx: number, wy: number, wz: number): number {
    let fx = Math.cos(camHeading)
    let fy = Math.sin(camHeading)
    let rx = wrapDelta(wx - camX)
    let ry = wrapDelta(wy - camY)
    let depth = rx * fx + ry * fy
    if (depth < 5) {
        return 0
    }
    screenX = 80 + (rx * (0 - fy) + ry * fx) / (FOV * depth) * 80
    screenY = (camZ - wz) * SCALE / depth + HORIZON
    return depth
}
function pickSize (list: Image[], scale: number): Image {
    let i = Math.min(SIZES - 1, Math.round(scale * SIZES) - 1)
    if (i < 0) {
        return null
    }
    return list[i]
}
// نرسم الصورة ونقص الجزء اللي ورا الطعس | draw the picture, cutting the part behind the dune
function drawClipped (target: Image, pic: Image, x: number, bottom: number, occ: number) {
    if (pic == null) {
        return
    }
    let top = bottom - pic.height
    if (top >= occ) {
        return
    }
    if (bottom <= occ + 1) {
        target.drawTransparentImage(pic, x - pic.width / 2, top)
    } else {
        let part = pic.clone()
        part.fillRect(0, occ - top, part.width, part.height, 0)
        target.drawTransparentImage(part, x - pic.width / 2, top)
    }
}
function drawThings (target: Image) {
    // من البعيد للقريب | far to near
    let order: number[] = []
    for (let t = 0; t < thingX.length; t++) {
        if (thingDepth[t] > 8) {
            let k = 0
            while (k < order.length && thingDepth[order[k]] > thingDepth[t]) {
                k += 1
            }
            order.insertAt(k, t)
        }
    }
    let walk = Math.floor(game.runtime() / 250) % 2
    for (let t of order) {
        let kind = thingKind[t]
        let gz = groundAt(thingX[t], thingY[t])
        let depth = project(thingX[t], thingY[t], gz)
        if (depth <= 0) {
            continue
        }
        if (kind == T_FLAG) {
            drawClipped(target, pickSize(sizesFlag, 169 / depth), screenX + 6, screenY, thingOcc[t])
        } else if (kind == T_TENT) {
            drawClipped(target, pickSize(sizesTent, 194 / depth), screenX, screenY, thingOcc[t])
        } else if (kind == T_FIRE) {
            if (Math.floor(game.runtime() / 150) % 2 == 0) {
                drawClipped(target, pickSize(sizesFire1, 142 / depth), screenX, screenY, thingOcc[t])
            } else {
                drawClipped(target, pickSize(sizesFire2, 142 / depth), screenX, screenY, thingOcc[t])
            }
        } else if (kind == T_CAMEL) {
            let rel = camelHead[thingRef[t]] - camHeading
            let goingRight = Math.sin(rel) > 0
            let list = sizesCamelL1
            if (goingRight && walk == 0) {
                list = sizesCamelR1
            } else if (goingRight) {
                list = sizesCamelR2
            } else if (walk == 1) {
                list = sizesCamelL2
            }
            drawClipped(target, pickSize(list, 150 / depth), screenX, screenY, thingOcc[t])
        } else if (kind == T_CAR) {
            let i = thingRef[t]
            let rel = aiHead[i] - camHeading
            let dir = Math.round(rel / (Math.PI / 4))
            dir = (dir % 8 + 8) % 8
            let lists = sizesAiRed
            if (i % 2 == 1) {
                lists = sizesAiGrey
            }
            drawClipped(target, pickSize(lists[dir], 70 / depth), screenX, screenY, thingOcc[t])
            // غبار وراها | dust behind it
            if (depth < 500 && Math.percentChance(40)) {
                addParticle(screenX + Math.randomRange(-4, 4), screenY - 1, Math.randomRange(-15, 15), Math.randomRange(-20, -5), 1, 0.5, 3)
            }
        }
    }
}

function nearestIndex (list: number[], v: number): number {
    let best = 0
    for (let i = 0; i < list.length; i++) {
        if (Math.abs(list[i] - v) < Math.abs(list[best] - v)) {
            best = i
        }
    }
    return best
}
function drawCar (target: Image) {
    if (project(carX, carY, carZ) <= 0) {
        return
    }
    let pic: Image = null
    if (game.runtime() < tumbleUntil) {
        pic = tumbleFrames[Math.floor(game.runtime() / 90) % tumbleFrames.length]
    } else {
        let pi = nearestIndex(PITCH_STEPS, pitch + bodyPitch)
        let ri = nearestIndex(ROLL_STEPS, totalTilt())
        pic = carFrames[pi * ROLL_STEPS.length + ri]
    }
    if (airborne) {
        let sx = screenX
        let sy = screenY
        if (project(carX, carY, groundAt(carX, carY)) > 0) {
            target.fillRect(screenX - 12, screenY - 2, 24, 3, 6)
        }
        screenX = sx
        screenY = sy
    }
    target.drawTransparentImage(pic, screenX - CAR_CENTER_X, screenY - CAR_GROUND_Y - bodyY * 1.4)
    // ذيل الرمل من الكفرات | sand spray from the tyres
    if (!(airborne) && raceStarted && Math.abs(speed) > 40) {
        let amount = 1
        if (controller.A.isPressed()) {
            amount = 2
        }
        if (sliding) {
            amount = 4
        }
        for (let i = 0; i < amount; i++) {
            let side = -11
            if (i % 2 == 1) {
                side = 11
            }
            addParticle(screenX + side + Math.randomRange(-2, 2), screenY - 2, Math.randomRange(-25, 25) - steerNow * 30, Math.randomRange(-45, -15), 1, 0.5, 3 + Math.randomRange(0, 1))
        }
    }
}
function dustBurst (n: number) {
    for (let i = 0; i < n; i++) {
        addParticle(80 + Math.randomRange(-22, 22), 100 + Math.randomRange(-8, 6), Math.randomRange(-35, 35), Math.randomRange(-40, -10), 2, 0.8, 4)
    }
}
function addParticle (x: number, y: number, vx: number, vy: number, r: number, life: number, c: number) {
    if (partX.length > 60) {
        return
    }
    partX.push(x)
    partY.push(y)
    partVX.push(vx)
    partVY.push(vy)
    partR.push(r)
    partLife.push(life)
    partColor.push(c)
}
function updateParticles (dt: number) {
    for (let i = partX.length - 1; i >= 0; i--) {
        partLife[i] += 0 - dt
        if (partLife[i] <= 0) {
            partX.removeAt(i)
            partY.removeAt(i)
            partVX.removeAt(i)
            partVY.removeAt(i)
            partR.removeAt(i)
            partLife.removeAt(i)
            partColor.removeAt(i)
        } else {
            partX[i] += partVX[i] * dt
            partY[i] += partVY[i] * dt
            partVY[i] += 60 * dt
            partR[i] += dt * 4
        }
    }
}
function drawParticles (target: Image) {
    for (let i = 0; i < partX.length; i++) {
        target.fillCircle(partX[i], partY[i], partR[i], partColor[i])
    }
}

// =====================================================
//  عداد الميلان | Tilt gauges
// =====================================================
function zoneColor (angle: number): number {
    let a = Math.abs(angle)
    if (a < SAFE_TILT) {
        return 1
    } else if (a < DANGER_TILT) {
        return 13
    }
    return 14
}
function drawDial (target: Image, cx: number, cy: number, angle: number, sideView: boolean) {
    target.fillCircle(cx, cy, 15, 15)
    target.drawCircle(cx, cy, 15, 11)
    for (let d = -50; d <= 50; d += 5) {
        let r = d * Math.PI / 180
        target.setPixel(cx + Math.sin(r) * 13, cy - Math.cos(r) * 13, zoneColor(d))
        target.setPixel(cx + Math.sin(r) * 12, cy - Math.cos(r) * 12, zoneColor(d))
    }
    let rad = angle * Math.PI / 180
    target.drawLine(cx, cy, cx + Math.sin(rad) * 11, cy - Math.cos(rad) * 11, zoneColor(angle))
    let c = Math.cos(rad)
    let s = Math.sin(rad)
    let w = 6
    let h = 3
    if (sideView) {
        w = 8
        h = 2
    }
    for (let k = 0 - h; k <= h; k++) {
        target.drawLine(cx - w * c - k * s, cy + 4 - w * s + k * c, cx + w * c - k * s, cy + 4 + w * s + k * c, 1)
    }
    if (sideView) {
        for (let k = 1; k <= 3; k++) {
            target.drawLine(cx - 6 * c + (h + k) * s, cy + 4 - 6 * s - (h + k) * c, cx + 2 * c + (h + k) * s, cy + 4 + 2 * s - (h + k) * c, 1)
        }
    }
    let txt = Math.abs(Math.round(angle)) + ""
    target.print(txt, cx - txt.length * 3 + 1, cy + 9, zoneColor(angle), image.font5)
}
function drawGauges (target: Image) {
    let tilt = totalTilt()
    drawDial(target, 17, 102, tilt, false)
    drawDial(target, 143, 102, 0 - pitch, true)
    target.print("SIDE", 7, 82, 1, image.font5)
    target.print("SLOPE", 130, 82, 1, image.font5)
}
function drawHud (target: Image) {
    target.fillRect(0, 0, 160, 10, 15)
    let seconds = 0
    if (raceStarted) {
        seconds = Math.floor((game.runtime() - startTime) / 100) / 10 + penalty
    }
    if (raceOver) {
        seconds = finalTime
    }
    target.print(seconds + "s", 2, 1, 1)
    target.print(Math.abs(Math.round(speed * 0.36)) + " km/h", 44, 1, 1)
    target.print("FLAG " + Math.min(nextFlag + 1, FLAG_COUNT) + "/" + FLAG_COUNT, 98, 1, 13)
    if (nextFlag < flagX.length && raceStarted) {
        let dx = wrapDelta(flagX[nextFlag] - carX)
        let dy = wrapDelta(flagY[nextFlag] - carY)
        let a = Math.atan2(dy, dx) - camHeading
        let ax = Math.sin(a)
        let ay = 0 - Math.cos(a)
        target.drawLine(80 - ax * 6, 18 - ay * 6, 80 + ax * 6, 18 + ay * 6, 13)
        target.drawLine(80 + ax * 6, 18 + ay * 6, 80 + ax * 2 - ay * 4, 18 + ay * 2 + ax * 4, 13)
        target.drawLine(80 + ax * 6, 18 + ay * 6, 80 + ax * 2 + ay * 4, 18 + ay * 2 - ax * 4, 13)
        let label = Math.round(Math.sqrt(dx * dx + dy * dy) / 10) + "m"
        if (nextFlag == flagX.length - 1) {
            label = label + " CAMP"
        }
        target.print(label, 89, 15, 1, image.font5)
    }
    if (game.runtime() < messageUntil) {
        let mw = message.length * 6 + 6
        target.fillRect(80 - mw / 2, 44, mw, 12, 15)
        target.print(message, 80 - mw / 2 + 3, 46, 13)
    }
}

// =====================================================
//  الأعلام والمخيم | Flags and the camp
// =====================================================
function placeFlags () {
    for (let f = 0; f < FLAG_COUNT; f++) {
        let col = f % 4
        let row = Math.floor(f / 4)
        if (row % 2 == 1) {
            col = 3 - col
        }
        let cx = Math.floor(carX / CELL + (col + 1) * MAP / 5)
        let cy = Math.floor(carY / CELL + (row - 1) * MAP / 3.2)
        let best = -1
        let bx = cx
        let by = cy
        for (let y = cy - 10; y <= cy + 10; y += 2) {
            for (let x = cx - 10; x <= cx + 10; x += 2) {
                if (cellH(x, y) > best) {
                    best = cellH(x, y)
                    bx = x
                    by = y
                }
            }
        }
        flagX.push(bx * CELL)
        flagY.push(by * CELL)
    }
    // المخيم عند آخر علم | the camp is at the last flag
    campX = flagX[flagX.length - 1] + 50
    campY = flagY[flagY.length - 1] - 20
}
function checkFlags () {
    if (raceOver || nextFlag >= flagX.length) {
        return
    }
    let dx = wrapDelta(flagX[nextFlag] - carX)
    let dy = wrapDelta(flagY[nextFlag] - carY)
    if (dx * dx + dy * dy < 60 * 60) {
        nextFlag += 1
        music.play(music.melodyPlayable(music.baDing), music.PlaybackMode.InBackground)
        for (let h of flagHandlers) {
            h()
        }
        if (nextFlag >= flagX.length) {
            raceOver = true
            finalTime = Math.floor((game.runtime() - startTime) / 100) / 10 + penalty
            say("CAMP! " + finalTime + "s", 4000)
            effects.confetti.startScreenEffect()
            control.runInParallel(function () {
                pause(3000)
                game.splash("TIME: " + finalTime + "s", "Crashes: " + rollovers)
                game.gameOver(true)
            })
        } else {
            say("FLAG " + nextFlag + "!", 900)
        }
    }
}

// =====================================================
//  البداية | Start
// =====================================================
function setDayPalette () {
    image.setPalette(hex`000000ffffff8a1538f0c47ed08a47a864346e3f2a9fd8f04f9dd4f8e2b89c94885e5850e3a961ffd24ae0402f1a1410`)
}
function setSunsetPalette () {
    image.setPalette(hex`000000ffffff8a1538f2b27ad97e4ba8573a6e3530f4946a5b3e7afad3b09c8c885e5060e89a60ffd45ee0402f1a1218`)
}
function startGame () {
    if (timeOfDay == DayTime.Sunset) {
        setSunsetPalette()
    } else {
        setDayPalette()
    }
    sizesFlag = makeSizes(imgFlag)
    sizesTent = makeSizes(imgTent)
    sizesFire1 = makeSizes(imgFire1)
    sizesFire2 = makeSizes(imgFire2)
    sizesCamelR1 = makeSizes(imgCamel1)
    sizesCamelR2 = makeSizes(imgCamel2)
    sizesCamelL1 = makeSizes(flipped(imgCamel1))
    sizesCamelL2 = makeSizes(flipped(imgCamel2))
    for (let d = 0; d < 8; d++) {
        sizesAiRed.push(makeSizes(aiFrames[d]))
        sizesAiGrey.push(makeSizes(recolor(aiFrames[d], 14, 10, 2, 11)))
    }
    buildDunes()
    // نبدأ في مكان منبسط | start on flat ground
    let bestFlat = 9999
    for (let y = 0; y < MAP; y += 4) {
        for (let x = 0; x < MAP; x += 4) {
            let flat = Math.abs(cellH(x + 2, y) - cellH(x - 2, y)) + Math.abs(cellH(x, y + 2) - cellH(x, y - 2)) + cellH(x, y) * 0.05
            if (flat < bestFlat) {
                bestFlat = flat
                carX = x * CELL
                carY = y * CELL
            }
        }
    }
    carZ = groundAt(carX, carY)
    lastGround = carZ
    camZ = carZ + CAM_UP
    placeFlags()
    spawnWorld()
    heading = Math.atan2(wrapDelta(flagY[0] - carY), wrapDelta(flagX[0] - carX))
    camHeading = heading
    let lastTime = game.runtime()
    scene.createRenderable(0, function (target: Image, camera: scene.Camera) {
        if (RENDER_STYLE == 0) {
            drawTerrain(target)
        } else {
            drawTerrainSmooth(target, RENDER_STYLE == 2)
        }
        drawThings(target)
        drawParticles(target)
        drawCar(target)
        drawGauges(target)
        drawHud(target)
    })
    game.onUpdate(function () {
        let now = game.runtime()
        let dt = Math.min(0.05, (now - lastTime) / 1000)
        lastTime = now
        updateCar(dt)
        updateWorld(dt)
        updateCamera(dt)
        updateParticles(dt)
        checkFlags()
        engineSound()
    })
    game.splash("TATEES", "Dune bashing!")
    game.showLongText("A = GAS\\nB = BRAKE/BACK\\nLEFT/RIGHT = STEER\\nReach the flags!\\nSlow down before big jumps!", DialogLayout.Center)
    say("3", 800)
    pause(900)
    say("2", 800)
    pause(900)
    say("1", 800)
    pause(900)
    say("GO!", 800)
    music.play(music.tonePlayable(660, music.beat(BeatFraction.Half)), music.PlaybackMode.InBackground)
    raceStarted = true
    startTime = game.runtime()
}

